namespace CheckoutPricing.UnitTest.ShippingFee;

public sealed class ShippingFeeTests
{
    private static int Fee(int payableTotalCents, LoyaltyTier tier, bool express) =>
        new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(payableTotalCents, tier, express));

    [Theory]
    [InlineData(4_999, LoyaltyTier.Bronze, 490)]
    [InlineData(5_000, LoyaltyTier.Bronze, 0)]
    [InlineData(4_999, LoyaltyTier.Silver, 490)]
    public void S11_StandardShippingIsFreeFromFiftyEurosPayable(int total, LoyaltyTier tier, int fee) =>
        Assert.Equal(fee, Fee(total, tier, express: false));

    [Theory]
    [InlineData(LoyaltyTier.Gold)]
    [InlineData(LoyaltyTier.Platinum)]
    public void S12_GoldAndPlatinumMembersNeverPayStandardShipping(LoyaltyTier tier) =>
        Assert.Equal(0, Fee(1_000, tier, express: false));

    [Theory]
    [InlineData(10_000, LoyaltyTier.Bronze, 990)]
    [InlineData(1_000, LoyaltyTier.Gold, 990)]
    [InlineData(1_000, LoyaltyTier.Platinum, 0)]
    public void S13_ExpressShippingCostsNinetyNineHundredthsFreeForPlatinumOnly(int total, LoyaltyTier tier, int fee) =>
        Assert.Equal(fee, Fee(total, tier, express: true));
}

