+namespace CheckoutPricing.Domain;
+
+public static class DiscountPolicy
+{
+    private const int LoyaltyMinimumSubtotalCents = 3_000;
+    private const int LoyaltyCapCents = 2_000;
+    private const int WelcomeCents = 500;
+    private const int SummerPercent = 10;
+    private const int SummerCapCents = 1_500;
+
+    public static int TotalDiscountCents(LoyaltyTier tier, int subtotalCents, string? promoCode)
+    {
+        var loyaltyCents = LoyaltyCents(tier, subtotalCents);
+        var promoCents = PromoCents(promoCode, subtotalCents - loyaltyCents);
+        return Math.Min(loyaltyCents + promoCents, subtotalCents);
+    }
+
+    private static int LoyaltyCents(LoyaltyTier tier, int subtotalCents) =>
+        subtotalCents < LoyaltyMinimumSubtotalCents
+            ? 0
+            : Math.Min(LoyaltyDiscountPolicy.DiscountCents(tier, subtotalCents), LoyaltyCapCents);
+
+    private static int PromoCents(string? promoCode, int remainingCents)
+    {
+        if (string.Equals(promoCode, "WELCOME5", StringComparison.OrdinalIgnoreCase))
+        {
+            return WelcomeCents;
+        }
+
+        if (string.Equals(promoCode, "SUMMER10", StringComparison.OrdinalIgnoreCase))
+        {
+            return Math.Min(remainingCents * SummerPercent / 100, SummerCapCents);
+        }
+
+        return 0;
+    }
+}

